text:
{
  "headline": "FDA's records trace our supply to plants with OAI classifications and recalls before and after the 2022-01-13 shortage posting",
  "headline_cites": ["D13", "D14", "D15", "D16", "D17", "D24", "D18", "D19", "D20", "D21", "D22", "D23", "E20", "E22", "E26", "E32", "E35", "E38", "E46", "E48", "E58", "E61", "E63", "E65", "E66", "E79", "E81", "E83"],
  "sentences": [
    {
      "text": "FDA first posted the dextrose monohydrate shortage on 2022-01-13 and it remains current as of 2026-10-21.",
      "cites": ["E117", "E109", "E110", "E111", "E112", "E113", "E114"]
    },
    {
      "text": "Multiple manufacturers supplying our sites have FDA inspection histories that include OAI classifications and recalls both before and after the shortage posting.",
      "cites": ["D13", "D14", "D15", "D16", "D17", "D24", "D18", "D19", "D20", "D21", "D22", "D23"]
    },
    {
      "text": "B. Braun US Pharmaceutical Manufacturing LLC (FEI 2021236) received an OAI classification letter dated 2020-10-22, 448 days before the shortage posting, and a later inspection ending 2025-11-21 was also classified OAI.",
      "cites": ["D24", "E20", "E22", "E26", "E28"]
    },
    {
      "text": "Baxter Healthcare Corporation plants (FEI 1025114, 1416980, 2618677, 2649614) have multiple OAI inspections, including inspections ending 2012-11-16, 2016-02-26, 2024-02-09, 2024-08-01, 2026-04-02, 2010-08-26, 2013-04-19, 2014-02-11, 2015-05-01, and 2016-10-03.",
      "cites": ["E32", "E35", "E38", "E46", "E48", "E58", "E61", "E63", "E65", "E66"]
    },
    {
      "text": "Hospira, Inc. (FEI 1021343) received OAI classifications for inspections ending 2010-01-19, 2011-06-17, and 2011-08-04, with a warning letter issued 2010-04-12.",
      "cites": ["E79", "E81", "E83", "E88"]
    },
    {
      "text": "Class I recall D-1257-2020 by B. Braun Medical Inc started 2020-04-18 (635 days before posting) and Class II recall D-0076-2021 by Baxter Healthcare Corporation started 2020-10-07 (463 days before posting) both involved dextrose-containing products.",
      "cites": ["D14", "D15", "E90", "E91"]
    },
    {
      "text": "The best available option is to transfer 89 bags of 50 g/1000 mL, 250 mL from Corvale General to Corvale East, which would increase Corvale East's supply from 2.4 days to 5 days while Corvale General retains 14 days.",
      "cites": ["D1", "D2", "D26"]
    }
  ]
}
